  locations:[{id:'loc-a',station:'s1',parent:null,name:'อาคาร A',kind:'อาคาร'},{id:'loc-a-er',station:'s1',parent:'loc-a',name:'ER และห้องพักแพทย์',kind:'พื้นที่'},{id:'loc-a-pharmacy',station:'s1',parent:'loc-a',name:'ห้องยา',kind:'พื้นที่'},{id:'loc-b',station:'s1',parent:null,name:'อาคาร B',kind:'อาคาร'},{id:'loc-b-pharmacy',station:'s1',parent:'loc-b',name:'ห้องยา',kind:'พื้นที่'},{id:'loc-p2-1',station:'s2',parent:null,name:'อาคาร 1',kind:'อาคาร'},{id:'loc-p2-laundry',station:'s2',parent:'loc-p2-1',name:'แผนกซักฟอก',kind:'แผนก'},{id:'loc-p2-waste',station:'s2',parent:'loc-p2-1',name:'ห้องขยะติดเชื้อ',kind:'พื้นที่'}],
  assetLocations:{'AC-004718':'loc-a-er','AC-002445':'loc-a-pharmacy','AC-001238':'loc-a-er','AC-005052':'loc-b-pharmacy','AC-003102':'loc-p2-1','AC-003042':'loc-p2-laundry','P1-AIR-A-1-001':'loc-a-er','P1-AIR-A-1-003':'loc-a-er','P2-AIR-1-1-001':'loc-p2-waste','P2-AIR-1-1-003':'loc-p2-laundry'},
