function tr(value){return TH[value]||value}
function localize(root=document.body){
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  let node;while(node=walker.nextNode()){let raw=node.nodeValue,trim=raw.trim();if(!trim)continue;let next=tr(trim);next=next.replace(/^Repair · /,'ซ่อม · ').replace(/^MA · /,'บำรุงรักษา · ').replace(/^Inspection · /,'ตรวจสอบ · ').replace(' from last week',' จากสัปดาห์ก่อน').replace(' compared to July',' เทียบเดือนกรกฎาคม').replace(' · 2 this month',' · 2 งานในเดือนนี้');if(next!==trim)node.nodeValue=raw.replace(trim,next)}
  root.querySelectorAll('[placeholder]').forEach(x=>x.placeholder=tr(x.placeholder));
}
TH['MA planner']='วางแผน MA';TH['ดูใบงาน →']='ดูใบงาน →';
const originalRender=render;render=function(){originalRender();localize(document.body)};
render();
function planMa(locationId=''){let options=state.locations.filter(l=>!l.parent).map(l=>`<option value="${l.id}" ${l.id===locationId?'selected':''}>${esc(station(l.station).name)} · ${esc(l.name)}</option>`).join('');modal('กำหนด MA เป็นกลุ่ม',`<div class="form"><div class="friendly-note"><span>🗓️</span><div>เครื่องทุกตัวในพื้นที่ที่เลือกจะมี <b>วัน MA เดียวกัน</b> และจะสร้างใบงาน MA แยกให้แต่ละเครื่อง</div></div><label>เลือกอาคาร / กลุ่มพื้นที่<select name="maLocation">${options}</select></label><label>วันที่นัดทำ MA<input required name="maDate" type="date" value="2026-09-15"></label><label>หมายเหตุ (ถ้ามี)<textarea name="note" placeholder="เช่น MA ประจำรอบ 6 เดือน อาคาร A"></textarea></label></div><div class="form-actions"><button type="button" class="btn secondary" data-action="close-modal">ยกเลิก</button><button class="btn primary">สร้างแผน MA</button></div>`) }
document.addEventListener('click',e=>{let el=e.target.closest('[data-action="plan-ma"]');if(el)planMa(el.dataset.id)});
document.addEventListener('submit',e=>{if(!e.target.matches('.modal')||e.target.dataset.form!=='กำหนด MA เป็นกลุ่ม')return;e.preventDefault();let f=new FormData(e.target),loc=locationNode(f.get('maLocation')),ids=branchLocations(loc.id),items=state.assets.filter(a=>ids.includes(state.assetLocations[a.id])),date=f.get('maDate'),note=f.get('note')||`MA ตามรอบ ${loc.name}`;if(!items.length)return toast('ไม่พบเครื่องแอร์ในพื้นที่นี้');items.forEach((a,index)=>{a.nextMa=thaiDate(date);a.health='ma_due';state.jobs.unshift({id:'JOB-MA-'+Date.now().toString().slice(-7)+'-'+String(index+1).padStart(2,'0'),station:a.station,asset:a.id,customer:station(a.station).name,description:`MA กลุ่ม ${loc.name} · ${note}`,status:'pending',assignee:'Unassigned',age:'now',type:'MA',date:date})});save();closeModal();toast(`สร้างแผน MA ${items.length} เครื่องแล้ว`);view='ma-plan';render()});
function forceThai(root=document.body){const words={'New work order':'สร้างใบงาน','Record service':'บันทึกงานบริการ','Start task':'เริ่มทำงาน','Complete':'ปิดงาน','View':'ดูรายละเอียด','Attention needed':'ต้องตรวจสอบ','Need attention':'ต้องติดตาม','Completed jobs':'งานเสร็จแล้ว','Station staff':'เจ้าหน้าที่ Station','Admin console':'ผู้ดูแลระบบ','Checklists':'รายการตรวจสอบ','Paknampo 1 Hospital':'โรงพยาบาลปากน้ำโพ 1','Paknampo 2 Hospital':'โรงพยาบาลปากน้ำโพ 2','Overdue 3 days':'เกินกำหนด 3 วัน','Overdue 1 day':'เกินกำหนด 1 วัน','Due in 12 days':'ครบกำหนดใน 12 วัน','Due in 22 days':'ครบกำหนดใน 22 วัน','Due in 16 days':'ครบกำหนดใน 16 วัน','Due in 4 days':'ครบกำหนดใน 4 วัน','28 Aug':'28 ส.ค.','28 Aug 2026':'28 ส.ค. 2569','Repair':'ซ่อม'};const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){let raw=node.nodeValue,next=raw;Object.entries(words).forEach(([from,to])=>{next=next.split(from).join(to)});next=next.replace(/(\d+) tasks/g,'$1 งาน').replace(/REPAIR/g,'ซ่อม');if(next!==raw)node.nodeValue=next}}
const friendlyRender=render;render=function(){friendlyRender();forceThai(document.body)};render();
function forceThaiDates(root=document.body){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){node.nodeValue=node.nodeValue.replace(/(\d{1,2}) ส\.ค\. 2026/g,'$1 ส.ค. 2569').replace(/Scan equipment QR/g,'สแกน QR เครื่อง')}}
const finalRender=render;render=function(){finalRender();forceThaiDates(document.body)};render();
function renderMobileNav(){let items=role==='admin'?[['dashboard','▦','ภาพรวม'],['jobs','▤','ใบงาน'],['assets','❄','เครื่องแอร์'],['ma-plan','◷','รอบ MA']]:[['today','▦','วันนี้'],['my-jobs','▤','ใบงาน'],['equipment','❄','เครื่องแอร์'],['scan','▣','สแกน QR']];let nav=document.querySelector('.mobile-nav');if(!nav){nav=document.createElement('nav');nav.className='mobile-nav';document.body.appendChild(nav)}nav.innerHTML=items.map(([id,icon,label])=>`<button data-nav="${id}" class="${view===id?'active':''}"><i>${icon}</i><span>${label}</span></button>`).join('')}
const responsiveRender=render;render=function(){responsiveRender();renderMobileNav()};render();
